#[no_mangle]
pub extern "C" fn lorentz_transformation_four_vector(v:*const i64,n:usize)->f64{if n!=6||v.is_null(){return -1e300}let a=unsafe{std::slice::from_raw_parts(v,n)};let (vel,s,t,x,y,z)=(a[0],a[1],a[2],a[3],a[4],a[5]);if vel<1||vel>200000000||s<0||s>3||t< -1000000||t>1000000||x< -100000000||x>100000000||y< -100000000||y>100000000||z< -100000000||z>100000000{return -1e300}let b=vel as f64/299792458.0;let g=1.0/(1.0-b*b).sqrt();let ct=(t as f64/1e6)*299792458.0;let xx=x as f64/100.0;let yy=y as f64/100.0;let zz=z as f64/100.0;[g*ct-g*b*xx,-g*b*ct+g*xx,yy,zz][s as usize]}
